    'network_genealogy_o2' => 'You can guide your team using up-to-date lists you download.',
    'network_genealogy_o3' => 'Rank progress is shown next to your team\'s health.',
    'network_genealogy_purpose' => 'The team tree drives referral commissions, rank qualification, and the leader\'s view of the team.',
    'network_genealogy_s1' => 'Open My team → Team to copy your code and share the Join Poster or QR code.',
    'network_genealogy_s10' => 'If you suspect someone has opened fake extra accounts, report it to Support with proof.',
    'network_genealogy_s2' => 'Send interested people to the official join form on the website, with your code already filled in.',
    'network_genealogy_s3' => 'Check how deep your team goes and who is active.',
    'network_genealogy_s4' => 'Use filters or search when the list is long.',
    'network_genealogy_s5' => 'Download the list (CSV) when you need it for offline training.',
    'network_genealogy_s6' => 'Check Ranks along with Network to see your qualification progress.',
    'network_genealogy_s7' => 'Staff/owner: use the “Who is under whom” tab when checking support requests, and record any change of referrer as per company rules.',
    'network_genealogy_s8' => 'Never collect a new member\'s password. They create their own login.',
    'network_genealogy_s9' => 'Check that new members appear under the right referrer within the expected time.',
    'network_genealogy_summary' => 'Invite partners with your code or QR, watch your team, and download lists.',
    'network_genealogy_t1' => 'Use one official invite link per campaign so tracking stays clear.',
    'network_genealogy_t2' => 'Referral commission is paid only on orders that are fully paid and delivered: :referral_rate% to the direct referrer, :gen2_rate% to the referrer one level above and :gen3_rate% to the one above that.',
    'network_genealogy_t3' => 'Area dealer rules affect sales areas. They are not the same as the referral team tree.',
    'network_genealogy_title' => 'Network, referrals, and team tree',
    'network_genealogy_w1' => 'Changing a referrer without permission is recorded in the work log. It is not an informal favour.',
    'network_genealogy_w2' => 'Do not sell “top positions” against company rules.',
    'network_genealogy_why' => 'Broken referral links or reused codes cause commission disputes that cannot be undone, so handle invites carefully.',
    'notifications_circulars_badge' => 'Notices & circulars',
    'notifications_circulars_o1' => 'You have a dated record of company instructions that affect your earnings and orders.',
    'notifications_circulars_o2' => 'Important unread notices are read and cleared on purpose, not ignored.',
    'notifications_circulars_purpose' => 'Company notices replace WhatsApp-only instructions for payment times, price changes, and rules.',
    'notifications_circulars_s1' => 'Press the bell for your own alerts (order status, payment updates, support replies). Partners also have them on the My updates tab under Contact the office → Notices.',
    'notifications_circulars_s2' => 'Partners: open Contact the office → Notices for company-wide rules and campaign messages.',
    'notifications_circulars_s3' => 'Mark a notice as read once you understand what you need to do.',
    'notifications_circulars_s4' => 'Only open links in notices that go to Madina panels or the official company website.',
    'notifications_circulars_s5' => 'Owners/staff: publish circulars from the Website/Content section with a clear start date.',
    'notifications_circulars_s6' => 'If someone gives you spoken instructions that differ from a circular, send a support request with the circular number.',
    'notifications_circulars_summary' => 'Read daily alerts, rule circulars, and account notices in one place.',
    'notifications_circulars_t1' => 'Pin or screenshot circulars about payment deadlines for your shop staff.',
    'notifications_circulars_t2' => 'A notice shows in your chosen language when a translation is available.',
    'notifications_circulars_title' => 'Notifications and company circulars',
    'notifications_circulars_w1' => 'Treat any unexpected “urgent payment” message from outside the panel as a scam until it is checked.',
    'notifications_circulars_why' => 'If you miss a circular, your withdrawal or payment may be rejected after a rule changes.',
    'owner_benefits_fund_badge' => 'Owners\' fund',
    'owner_benefits_fund_title' => 'The owners\' fund',
    'owner_benefits_fund_summary' => 'What is left of each order after the company share and all commissions. Only the owners see it.',
    'owner_benefits_fund_purpose' => 'Owner accounts need this money kept apart. It is a card on Treasury → Funds, on the owner panel only.',
    'owner_benefits_fund_why' => 'Keeping this money apart stops it being mixed with money owed to partners.',
    'owner_benefits_fund_s1' => 'Sign in on the owner panel and open Treasury → Funds.',
    'owner_benefits_fund_s2' => 'Press the Owners\' fund card to see every amount that came in and went out.',
    'owner_benefits_fund_s3' => 'Other staff see the company share and the owners\' share as one line, so the order still adds up.',
    'owner_benefits_fund_o1' => 'Only owners see this fund.',
    'owner_benefits_fund_t1' => 'Spending from this fund works like any other fund.',
    'owner_benefits_fund_w1' => 'Do not share this figure with staff or partners.',
    'payment_claims_badge' => 'Sending payment',
    'payouts_settlements_badge' => 'Paying partners',
    'payouts_settlements_title' => 'Paying partners and closing the month',
    'payouts_settlements_summary' => 'Withdrawal requests are paid one by one. Salary and rank money is shared out when the month is closed.',
    'payouts_settlements_purpose' => 'This chapter is for office staff who pay partners.',
    'payouts_settlements_why' => 'Paying on time and with a record keeps partners\' trust.',
    'payouts_settlements_s1' => 'Open Withdrawal requests to see what is waiting.',
    'payouts_settlements_s2' => 'Check each request and approve or reject it. Write a reason if you reject.',
    'payouts_settlements_s3' => 'Pay the money, then record the payment with its reference and receipt.',
    'payouts_settlements_s4' => 'To pay many at once, press Download bank file and send it to the bank.',
    'payouts_settlements_s5' => 'Month closing is on Treasury → Money tasks. Close a month only after all its orders are finished.',
    'payouts_settlements_o1' => 'Every payment has a person, a time and a receipt.',
    'payouts_settlements_t1' => 'When staff prepare a payment, a different person approves it. The owner can prepare and approve alone. Every step is noted in the work log.',
    'payouts_settlements_t2' => 'Filter the list by status and method to work through one batch at a time.',
    'payouts_settlements_w1' => 'Never pay without checking the account number on the request.',
    'place_codes_admin_badge' => 'Place code setup',
    'place_codes_admin_o1' => 'All areas where the company sells have complete codes.',
    'place_codes_admin_o2' => 'Every partner is linked to a valid code.',
    'place_codes_admin_purpose' => 'A clean list of area codes keeps area dealer rules and reports correct.',
    'place_codes_admin_s1' => 'Open Settings → Area codes (place codes).',
    'place_codes_admin_s2' => 'Go through Division / District / Upazila / Union / Pourashava.',
    'place_codes_admin_s3' => 'Add codes with clear names. The form can add the MNHC- start for you.',
    'place_codes_admin_s4' => 'Link partners to codes when they join or when you edit their account.',
    'place_codes_admin_s5' => 'Turn off old codes instead of reusing them for new places.',
    'place_codes_admin_s6' => 'Check the changes after updating many codes at once.',
    'place_codes_admin_s7' => 'After big changes, check the Area dealers page too.',
    'place_codes_admin_s8' => 'Publish a circular when many areas are changed.',
    'place_codes_admin_summary' => 'Create and keep up the Bangladesh area codes used for joining and sales areas.',
    'place_codes_admin_t1' => 'Keep a spreadsheet list of all areas as a backup.',
    'place_codes_admin_t2' => 'After adding Bangla names, test that search finds them.',
    'place_codes_admin_title' => 'Place code setup',
    'place_codes_admin_w1' => 'Do not rename codes already printed on partner ID cards without a plan to update the cards.',
    'place_codes_admin_w2' => 'Do not give the same exclusive area to two partners.',
    'place_codes_admin_why' => 'Duplicate or unused codes quietly link sales to the wrong person.',
    'profile_security_badge' => 'Profile & security',
    'profile_security_o1' => 'Your profile shows the same details used on invoices and ID cards.',
    'profile_security_o2' => 'Unknown logins are signed out, and you change your password if you think someone knows it.',
    'profile_security_o3' => 'Two-step login (2FA) is turned on when company rules require it.',
    'profile_security_purpose' => 'Your profile details are used on invoices, ID cards, payment accounts, and sales area. Security settings stop others from reaching your money.',
    'profile_security_s1' => 'Open Profile and check your full name, shop name, phone, email, and address as registered with the company.',
    'profile_security_s10' => 'Log out on shared computers when you finish.',
    'profile_security_s2' => 'Check your place code and sales area when shown. They affect area dealer rules and area reports.',
    'profile_security_s3' => 'Download your Partner ID Card PDF and Join Poster from Profile, when available, to bring in new members.',
    'profile_security_s4' => 'Open Security to change your password. Use a new password that you do not use anywhere else.',
    'profile_security_s5' => 'Check your logged-in devices and sign out any you do not know right away.',
    'profile_security_s6' => 'If two-step login (2FA) is on for staff, set it up and keep the recovery codes safe offline.',
    'profile_security_s7' => 'Change payment account details only in the profile or payment fields, never by chat message.',
    'profile_security_s8' => 'After an identity correction that needs staff approval, wait until your status is Active before big orders or payments.',
    'profile_security_s9' => 'Owners/staff: keep your staff profile separate from your partner account, even when both dashboards are linked.',
    'profile_security_summary' => 'Keep your shop details correct and protect your account with a password, device checks, and two-step login (2FA) if needed.',
    'profile_security_t1' => 'Upload photos of your NID or birth certificate only through the official joining form.',
    'profile_security_t2' => 'Share your Join Poster QR only in your own recruiting channels, so codes do not get mixed up.',
    'profile_security_t3' => 'Contact Support if Profile fields are locked. Partners cannot change all NID details themselves.',
    'profile_security_title' => 'Profile, identity documents, and security',
    'profile_security_w1' => 'Staff must never ask partners for their passwords when helping them.',
    'profile_security_w2' => 'Do not email scanned NID copies. Upload them only in the panel.',
    'profile_security_why' => 'A wrong phone or email stops OTP codes and notices from reaching you. Staying logged in on shared devices is a common way fraud happens in partner networks.',
    'ranks_royalties_badge' => 'Ranks, award & royalty',
    'ranks_royalties_o1' => 'You know your current rank and what is still needed for the next one.',
    'ranks_royalties_o2' => 'You know the two kinds of rank money: a one-time award and a monthly royalty.',
    'ranks_royalties_o3' => 'Leaders can plan training around the next rank target that can be measured, not rumours.',
    'ranks_royalties_purpose' => 'Ranks reward steady buying and a strong team. Each month the rank royalty fund (:royalty_rate% of every purchase) is shared among the dealers at each rank who kept their rank that month. You get royalty only for your latest rank.',
    'ranks_royalties_s1' => 'Open Ranks, or press “See my progress” in the Targets box on the Dashboard, to see your rank and what is left for the next one.',
    'ranks_royalties_s2' => 'The ranks: Marketing Officer (MO), Area Manager (AM), Sales Manager (SM), Marketing Executive (ME).',
    'ranks_royalties_s3' => 'MO counts your own purchases. AM, SM and ME count active dealers at the needed rank in your team (see the tips below).',
    'ranks_royalties_s4' => 'The one-time rank award is paid as soon as you reach a rank. If you reach MO and then AM in the same month, you get both awards.',
    'ranks_royalties_s5' => 'Staff: see rank rules under Commission rules. Do not give ranks by hand.',
    'ranks_royalties_s6' => 'Plan training around the next target you can measure, not around titles.',
    'ranks_royalties_s7' => 'Check ranks again after months with big deliveries.',
    'ranks_royalties_s8' => 'If there is a dispute, note the month and download your statement from My money.',
    'ranks_royalties_s9' => 'At month closing, if nobody qualifies at a rank, that rank\'s royalty goes to the company profit fund.',
    'ranks_royalties_summary' => 'Follow your progress from MO → AM → SM → ME, your one-time rank awards and your monthly royalty.',
    'ranks_royalties_t1' => 'MO: your own total purchases since you joined must reach :mo_target (one-time award :mo_bonus). AM: :am_count active dealers at MO or higher within :rank_depth levels of your team (award :am_bonus). SM: :sm_count at AM or higher (award :sm_bonus). ME: :me_count at SM or higher (award :me_bonus).',
    'ranks_royalties_t2' => 'In training, keep your own retail sales separate from your team\'s sales.',
    'ranks_royalties_t3' => 'To get royalty for your rank in a month, buy at least that rank\'s monthly amount in the same month: MO :mo_keep, AM :am_keep, SM :sm_keep, ME :me_keep. For the first :grace_days days after you reach a rank, you get it even without this.',
    'ranks_royalties_title' => 'Ranks, rank awards and monthly royalty',
    'ranks_royalties_w1' => 'Do not put earlier dates on orders to make it look like you qualify.',
    'ranks_royalties_w2' => 'Staff must not give ranks by hand outside the approved tools.',
    'ranks_royalties_why' => 'Partners often mistake a one-time jump in sales for steady qualification. Ranks follow fixed rules and dates.',
    'reports_badge' => 'Reports',
    'reports_title' => 'Reports and files',
    'reports_summary' => 'Partners have one My money page. The office has one Order report in Treasury, with files to download.',
    'reports_purpose' => 'Everything is on one page and can be filtered, so there is no need to add up several reports.',
    'reports_why' => 'One report means one set of figures.',
    'reports_s1' => 'Dealers and sub-dealers: open My money and use the search, filters and date view on the list.',
    'reports_s2' => 'Use Download on My money for your statement, the full report PDF and certificates.',
    'reports_s3' => 'Office: open Treasury → Order report. Press a row to see where every taka of that order went.',
    'reports_s4' => 'Use Download on the Order report for report files. You are offered only the files your job allows.',
    'reports_o1' => 'The figures on the screen and in the file are the same.',
    'reports_t1' => 'Money figures count delivered goods only.',
    'reports_w1' => 'Report files have names and money figures. Keep them inside the office.',
    'rewards_milestones_badge' => 'Target rewards',
    'rewards_milestones_o1' => 'Progress counts only eligible sales.',
    'rewards_milestones_o2' => 'Reward payments are recorded in the month-closing pages.',
    'rewards_milestones_purpose' => 'Long-term rewards keep leaders going beyond monthly commissions.',
    'rewards_milestones_s1' => 'Partners: press “See my progress” on the Dashboard to see each target. Staff: open Treasury → Money tasks → Rewards. Team sales needed now: bike :bike_target, car :car_target.',
    'rewards_milestones_s2' => 'Only orders that are fully paid and delivered count, from your whole team since the start. Each direct line counts up to a limit: :bike_cap for the bike, :car_cap for the car.',
    'rewards_milestones_s3' => 'The bike/car fund is not lost at month end. It carries over from month to month.',
    'rewards_milestones_s4' => 'Staff: pay rewards from Treasury → Money tasks → Rewards. Record the method and reference so a receipt can be made.',
    'rewards_milestones_s5' => 'Keep award or payment circulars with your records.',
    'rewards_milestones_s6' => 'Check the progress bar and eligible sales before asking Support.',
    'rewards_milestones_s7' => 'Owners: keep the money for rewards owed separate from daily running cash.',
    'rewards_milestones_summary' => 'Follow bike, car, and other rewards against your checked target sales.',
    'rewards_milestones_t1' => 'Take photos of award receipts for your records.',
    'rewards_milestones_t2' => 'Reward items are separate from the money you can withdraw.',
    'rewards_milestones_title' => 'Rewards and sales targets',
    'rewards_milestones_w1' => 'Do not promise unfinished targets to others as guaranteed money.',
    'rewards_milestones_why' => 'Only checked and paid sales count; spoken promises do not.',
    'staff_fulfillment_badge' => 'Order approval & delivery',
    'staff_fulfillment_o1' => 'Approved orders can be paid and delivered.',
    'staff_fulfillment_o2' => 'The sending branch matches the stock movement.',
    'staff_fulfillment_o3' => 'Checked payments show on the order.',
    'staff_fulfillment_purpose' => 'This work turns partner orders into delivered goods and correctly recorded cash.',
    'staff_fulfillment_s1' => 'Open the Orders list and filter by “waiting for approval”.',
    'staff_fulfillment_s10' => 'Match the value of goods sent each day with the money received on Treasury → Order report.',
    'staff_fulfillment_s2' => 'Check the items, prices, and partner status before you approve or reject.',
    'staff_fulfillment_s3' => 'Open Check order payments. Check the amount, method, screenshot and receiving account against the company\'s payment accounts.',
    'staff_fulfillment_s4' => 'Mark a payment as checked only when the money has really arrived.',
    'staff_fulfillment_s5' => 'Choose the delivery branch when more than one branch is in use.',
    'staff_fulfillment_s6' => 'Send the goods from Deliveries. Record the courier name and the tracking number.',
    'staff_fulfillment_s7' => 'Approve an order only when the checked payments equal the order total.',
    'staff_fulfillment_s8' => 'If fewer goods were sent, correct it with a written note as per company rules.',
    'staff_fulfillment_s9' => 'Report suspicious repeated small payments to a senior.',
    'staff_fulfillment_summary' => 'Approve orders after full payment, then send the goods.',
    'staff_fulfillment_t1' => 'Later, use Reports → Branch sales to see each branch\'s profit.',
    'staff_fulfillment_t2' => 'Write rejection reasons politely and say what the partner should do next.',
    'staff_fulfillment_title' => 'Order delivery: payment check, approval and sending',
    'staff_fulfillment_w1' => 'You cannot approve an order from your own linked dealer account, and nobody can skip this. Another staff member who handles orders must approve it.',
    'staff_fulfillment_w2' => 'Never skip payment checks “as a favour”.',
    'staff_fulfillment_why' => 'Approving without checking payment, or sending from the wrong branch, breaks the stock count and the records.',
    'staff_people_accounts_badge' => 'Staff & permissions',
    'staff_people_accounts_o1' => 'Every staff member has only the permissions they need.',
    'staff_people_accounts_o2' => 'Partner joining papers are saved with the account.',
    'staff_people_accounts_o3' => 'Two-dashboard access is given on purpose and can be removed.',
    'staff_people_accounts_purpose' => 'This part controls who can do what in the system and which permissions they get.',
    'staff_people_accounts_s1' => 'Open Staff → Staff list to add staff and set their permissions (orders, accounts, stock, content, work log, and so on).',
    'staff_people_accounts_s10' => 'Tell people about approvals through the panel status, not only by phone.',
    'staff_people_accounts_s11' => 'Owners: check the list of staff permissions from time to time.',
    'staff_people_accounts_s2' => 'Open Dealers & sub-dealers → Dealers to search dealers, see their status, and keep their codes and areas correct.',
    'staff_people_accounts_s3' => 'Open Dealers & sub-dealers → Sub-dealers to work with sub-dealers.',
    'staff_people_accounts_s4' => 'Open Applications: check the papers, then approve or reject with a reason.',
    'staff_people_accounts_s5' => 'Give a partner staff access only after formal approval.',
    'staff_people_accounts_s6' => 'Check the work log after changing permissions.',
    'staff_people_accounts_s7' => 'Before creating an account, check that the phone and email are not already in use.',
    'staff_people_accounts_s8' => 'Suspend an account that may be hacked before you look into it.',
    'staff_people_accounts_s9' => 'Before adding a new partner, plan the place code for their sales area.',
    'staff_people_accounts_summary' => 'Add staff, manage dealer and sub-dealer accounts, and handle partnership applications.',
    'staff_people_accounts_t1' => 'Write shop names the same way every time so search works well.',
    'staff_people_accounts_t2' => 'Check permissions again on the same day a person\'s role changes.',
    'staff_people_accounts_t3' => 'Keep the emergency owner login details sealed and stored offline.',
    'staff_people_accounts_title' => 'Staff and accounts: staff, partners, and joining',
    'staff_people_accounts_w1' => 'Never let several people share one staff login.',
    'staff_people_accounts_w2' => 'Do not approve an NID check without clear document photos.',
    'staff_people_accounts_why' => 'Staff with too many permissions and incomplete NID checks are the biggest daily risks.',
    'subdealer_salary_tour_badge' => 'Salary & tour fund',
    'subdealer_salary_tour_o1' => 'You can see how much salary you have earned this month that is not yet paid.',
    'subdealer_salary_tour_o2' => 'Paid amounts match the accounts month-end closing.',
    'subdealer_salary_tour_o3' => 'The tour fund is not mixed up with cash you can withdraw right away.',
    'subdealer_salary_tour_purpose' => 'Sub-dealers get :sub_salary_rate% salary on every purchase that is fully paid and delivered, with no minimum purchase. Another :sub_tour_rate% is saved in their own tour fund. The salary goes into My money after the month ends; the office uses the tour fund for company tours.',
    'subdealer_salary_tour_s1' => 'Press “See my progress” on your Dashboard to see salary earned but not yet paid. The money lines are on My money: choose Salary in the list filter.',
    'subdealer_salary_tour_s2' => 'Every purchase that is fully paid and delivered counts toward your salary. There is no minimum amount.',
    'subdealer_salary_tour_s3' => 'When shown, track the tour fund separately from the money you can use.',
    'subdealer_salary_tour_s4' => 'After month-end closing, check that the money shows on My money.',
    'subdealer_salary_tour_s5' => 'Dealers with sub-dealers: help them plan their sales. Do not lend personal cash against future salary.',
    'subdealer_salary_tour_s6' => 'Staff: run month-end salary from Treasury → Money tasks → Month close.',
    'subdealer_salary_tour_s7' => 'Match salary lines with the orders behind them.',
    'subdealer_salary_tour_s8' => 'Send a support request if month-end salary is recorded but does not match your delivered sales.',
    'subdealer_salary_tour_s9' => 'Your tour fund carries over from month to month. It does not reset when a month closes.',
    'subdealer_salary_tour_summary' => 'Understand the monthly salary and the tour fund that come from your purchases.',
    'subdealer_salary_tour_t1' => 'Keep your invoices. Each paid and delivered order adds to that month\'s salary.',
    'subdealer_salary_tour_t2' => 'Watch circulars for short-term salary offers or changes.',
    'subdealer_salary_tour_title' => 'Sub-dealer salary and tour fund',
    'subdealer_salary_tour_w1' => 'The tour fund is not cash to withdraw. The office uses it to send you on company tours.',
    'subdealer_salary_tour_w2' => 'Staff must not change salary percentages outside Commission rules & rates.',
    'subdealer_salary_tour_why' => 'Only orders that are fully paid and delivered count. If an order is later refunded, the salary on it is taken back.',
    'support_badge' => 'Help & support',
    'support_o1' => 'Most “how do I” questions are answered without waiting.',
    'support_o2' => 'Requests you send have enough detail for staff to check the problem.',
    'support_purpose' => 'Help yourself first to avoid delays. When a person must step in, a support request keeps a record.',
    'support_s1' => 'Open Help and search a word (order, withdrawal, branch, commission, and so on).',
    'support_s2' => 'In each chapter, read the purpose, why it matters, the steps, results, tips, and warnings.',
    'support_s3' => 'If a page stops you, follow the “finish these steps first” message and complete the earlier steps.',
    'support_s4' => 'Restart the live dashboard tour from Help if you want the screen guide again (the tour is shorter than the full manual).',
    'support_s5' => 'Send a support request with a topic, a subject, and full details, including order or withdrawal numbers.',
    'support_s6' => 'Attach screenshots or PDFs when the problem is on screen or about a payment.',
    'support_s7' => 'Follow the request status until it is solved, and send more proof if asked.',
    'support_s8' => 'Staff: work through the support request list, update the status, and close each one with a clear answer.',
    'support_summary' => 'Search this manual, restart the dashboard tour, and send support requests you can track.',
    'support_t1' => 'Search with Bangla or English words; many chapters can be found with both.',
    'support_t2' => 'Send one problem per request so it reaches the right person faster.',
    'support_title' => 'Help, user manual, and support requests',
    'support_w1' => 'Do not write passwords or full NID numbers in a support request.',
    'support_why' => 'Support only through Facebook or WhatsApp loses proof and has no promised reply time.',
    'website_customization_badge' => 'Website settings',
    'website_customization_o1' => 'The public website shows current offers and what is in stock.',
    'website_customization_o2' => 'Enquiries go into a list that can be followed up.',
    'website_customization_o3' => 'A clean, good-looking website helps bring in new dealers.',
    'website_customization_purpose' => 'The public website shows the brand and brings in new dealers. The panels handle the daily business work.',
    'website_customization_s1' => 'Open Website → Arrange the website to change the banners and public text, where allowed.',
    'website_customization_s2' => 'Show on the home page only products that are really in stock. Edit the product and choose Yes or No for “Show on home page?”.',
    'website_customization_s3' => 'Publish content and circulars for rules and campaigns.',
    'website_customization_s4' => 'Sort enquiries and reply on time.',
    'website_customization_s5' => 'Move partnership applications into account joining.',
    'website_customization_s6' => 'Check on mobile and computer before publishing.',
    'website_customization_s7' => 'Keep the map and contact details correct for the Pirganj office unless the company says otherwise.',
    'website_customization_s8' => 'When testing public pages, check both the day and night themes.',
    'website_customization_s9' => 'Upload images and videos within the size and file type limits.',
    'website_customization_summary' => 'Manage how products, notices, and incoming enquiries appear on the public website.',
    'website_customization_t1' => 'Use the official brand logos and images every time.',
    'website_customization_t2' => 'Do not post requests for money on public pages.',
    'website_customization_title' => 'Public website, content, enquiries, and partnership applications',
    'website_customization_w1' => 'Do not show staff-only links in public menus.',
    'website_customization_why' => 'Old banners and unanswered enquiries cost you dealers and customer trust.',
    'withdrawals_badge' => 'Withdrawing money',
    'withdrawals_title' => 'Withdrawing money',
    'withdrawals_summary' => 'Take your money to a bank or mobile account, or use it for an order.',
    'withdrawals_purpose' => 'This chapter shows how a withdrawal is asked for, checked and paid.',
    'withdrawals_why' => 'Every payment is checked before it is sent, so money goes only to the right person.',
    'withdrawals_s1' => 'Open My money and press Withdraw.',
    'withdrawals_s2' => 'Choose to take the money to a bank or mobile account, or to order with this money.',
    'withdrawals_s3' => 'For bank or mobile, fill in the amount and the account. The money is set aside until the office has checked it. Your request stays on My money so you can see what the office decided.',
    'withdrawals_s4' => 'For an order, you go to the order page with From My Account chosen. Nothing is taken until you place the order.',
    'withdrawals_s5' => 'Office: open Withdrawal requests to check and pay. The person who pays must add the receipt. A staff member who approved a request cannot pay it: someone else or the owner pays. The owner can approve and pay alone.',
    'withdrawals_o1' => 'Every withdrawal has one line in My money and a receipt once it is paid.',
    'withdrawals_t1' => 'Keep your bank or mobile number correct to avoid a returned payment.',
    'withdrawals_w1' => 'If the button is missing, read the notice on the page. It says why.',
    'payment_receipts_badge' => 'Payment receipts',
    'payment_receipts_title' => 'Payment receipts',
    'payment_receipts_summary' => 'A receipt for every payment the office made to you.',
    'payment_receipts_purpose' => 'A receipt opens from the line of that payment in My money.',
    'payment_receipts_why' => 'You have proof of every payment without asking the office.',
    'payment_receipts_s1' => 'Open My money and find the withdrawal line.',
    'payment_receipts_s2' => 'Press the line to open that withdrawal, then press the receipt button to view or print it.',
    'payment_receipts_s3' => 'Office: a receipt is made when a payment is recorded on Withdrawal requests.',
    'payment_receipts_o1' => 'Each paid withdrawal has one receipt number.',
    'payment_receipts_t1' => 'For your own records, use Download on My money.',
    'payment_receipts_w1' => 'A receipt cannot be changed after it is made.',
    'money_rules_badge' => 'Money rules',
    'money_rules_title' => 'Where your money comes from, and how each month closes',
    'money_rules_summary' => 'A short list of every commission, who gets it, and what happens to money at the end of each month.',
    'money_rules_purpose' => 'From every purchase, :dealer_fund_rate% (dealer purchase) or :sub_fund_rate% (sub-dealer purchase) goes to partners and funds. The rates below come from the live commission settings.',
    'money_rules_why' => 'When you know which money is paid at once, which waits for month end, and which needs a target, there are no surprises.',
    'money_rules_s1' => 'Only purchases that are fully paid and delivered count.',
    'money_rules_s2' => 'Cashback: the buyer gets :cashback_rate% of their own purchase back.',
    'money_rules_s3' => 'Referral: :referral_rate% to the person who referred the buyer, then :gen2_rate% and :gen3_rate% to the two people above them.',
    'money_rules_s4' => 'Area commission: :area_rate% shared among the area dealers of the buyer\'s place codes (management :area_management%, division :area_division%, district :area_district%, upazila :area_upazila%, Union / Pourashava :area_union%).',
    'money_rules_s5' => 'Dealer salary: :dealer_salary_rate% goes into the salary fund of the buyer\'s division. Dealers there who buy at least :dealer_salary_min that month share it equally.',
    'money_rules_s6' => 'Rank royalty: :royalty_rate% is shared each month among dealers who keep their rank. You get it only for your latest rank.',
    'money_rules_s7' => 'Rank award: :incentive_rate% builds the award fund. The one-time award is paid as soon as you reach a rank. Reaching MO and AM in the same month pays both.',
    'money_rules_s8' => 'Marketing (:marketing_rate%) and bike/car rewards (:vehicle_rate%) are company funds for campaigns and big rewards.',
    'money_rules_s9' => 'Each month closes on its own. If you miss a target (salary, area commission, royalty and so on), that month\'s money goes to the company profit fund, and the reason is recorded. It does not move to the next month.',
    'money_rules_s10' => 'Only three funds carry over from month to month: the rank award fund, the sub-dealer tour fund and the bike/car fund.',
    'money_rules_o1' => 'You can tell which money is paid at once and which waits for month end.',
    'money_rules_o2' => 'You know that a missed target means that month\'s share is lost, not saved for later.',
    'money_rules_t1' => 'Press “See my progress” on the Dashboard to see how close you are to each monthly target.',
    'money_rules_t2' => 'If the owner changes a rate, this page shows the new rate right away.',
    'money_rules_w1' => 'Do not wait for next month to make up a missed target. Each month is counted on its own.',
    'my_progress_badge' => 'My progress',
    'my_progress_title' => 'See my progress: salary, rank and rewards in one window',
    'my_progress_summary' => 'One button on your Dashboard shows how close you are to this month\'s salary, your next rank and the bike and car rewards.',
    'my_progress_purpose' => 'The progress window shows your targets for this month in simple bars, so you know what to buy and by when.',
    'my_progress_why' => 'Targets reset every month. Checking your progress early gives you time to reach them.',
    'my_progress_s1' => 'On the Dashboard, find the Targets box and press “See my progress”.',
    'my_progress_s2' => 'The top line shows this month\'s dates and how many days are left.',
    'my_progress_s3' => 'Monthly salary: dealers see how much more to buy to get this month\'s salary. Sub-dealers see the salary earned so far.',
    'my_progress_s4' => 'Rank and rank award (dealers): your rank now, the next rank, what is still needed, and your one-time award.',
    'my_progress_s5' => 'Keep your royalty: how much you must buy this month to get your rank\'s royalty.',
    'my_progress_s6' => 'Bike and car rewards: your team\'s total sales against each target.',
    'my_progress_s7' => 'Press Done to close it. The numbers are fresh each time you open the window.',
    'my_progress_o1' => 'You know exactly how much more to buy this month, and by which date.',
    'my_progress_o2' => 'You can see if your rank award is paid or still waiting.',
    'my_progress_t1' => 'Only orders that are paid and delivered count. An order waiting for payment check does not count yet.',
    'my_progress_t2' => 'Open it again near the end of the month before you place your last order.',
    'my_progress_w1' => 'The salary amount shown is an estimate. The final amount is paid after the month closes.',
    'office_chat_badge' => 'Chat with the office',
    'office_chat_title' => 'Messages between partners and the office',
    'office_chat_summary' => 'Partners send messages and photos to the office. The owner chooses which staff answer.',
    'office_chat_purpose' => 'Chat keeps every question and answer in the panel, so nothing is lost in personal phones.',
    'office_chat_why' => 'When the right staff answer, partners get help faster and the owner can see every chat.',
    'office_chat_s1' => 'Dealers and sub-dealers: open Contact the office → Messages.',
    'office_chat_s2' => 'Type your message. You can add a photo, for example a payment screenshot.',
    'office_chat_s3' => 'Staff: if the owner chose you, open Partner messages to read and answer.',
    'office_chat_s4' => 'Owner: open Partner messages and then “Who answers partner chat”.',
    'office_chat_s5' => 'For each staff member choose No, Own branches only, or Whole company, then press Save. “Own branches only” means they see chats only from partners of their own branches.',
    'office_chat_s6' => 'Owners always see every chat.',
    'office_chat_o1' => 'Every partner question has a written answer in the panel.',
    'office_chat_o2' => 'Only the staff the owner chose can read partner chats.',
    'office_chat_t1' => 'Give the order number in your message so staff can find it fast.',
    'office_chat_t2' => 'For a problem that needs a proper record, send a support request too.',
    'office_chat_w1' => 'Never send your password or OTP in chat.',
    'data_cleanup_badge' => 'Clear old data',
    'data_cleanup_title' => 'Clear old data: deleting old records you no longer need',
    'data_cleanup_summary' => 'The owner can delete old login codes, SMS records and closed enquiries. Nothing is deleted on its own.',
    'data_cleanup_purpose' => 'Old login codes and SMS records pile up. The owner can clear them by hand. Orders, payments, accounts, commissions and the work log are never shown here and can never be deleted here.',
    'data_cleanup_why' => 'Clearing old records keeps lists short. Making the owner choose each one keeps important data safe.',
    'data_cleanup_s1' => 'In the owner panel, open Settings → Clear old data.',
    'data_cleanup_s2' => 'Choose the kind: Old login codes, SMS records or Closed enquiries.',
    'data_cleanup_s3' => 'Choose “Older than (days)” and press Show.',
    'data_cleanup_s4' => 'Tick the records to delete, or “Select all on this page”.',
    'data_cleanup_s5' => 'Press Delete selected and confirm. Deleted records cannot be brought back.',
    'data_cleanup_o1' => 'Old records you chose are gone for good.',
    'data_cleanup_o2' => 'Business records stay safe, because they never appear on this page.',
    'data_cleanup_t1' => 'Keep at least a few weeks of SMS records in case a partner asks about a message.',
    'data_cleanup_t2' => 'Only the owner can see this page. Staff cannot.',
    'data_cleanup_w1' => 'Deleting cannot be undone. Check the list before you press Delete.',

    'courier_ordering_badge' => 'Courier',
    'courier_ordering_title' => 'Choosing a courier and following your parcel',
    'courier_ordering_summary' => 'Pick a courier when you order, or let the company decide. Then follow the parcel on the order page.',
    'courier_ordering_purpose' => 'The order form has a “Courier” box. It lists the couriers the owner has switched on, and “Company decides”.',
    'courier_ordering_why' => 'You can pick the courier that works best in your area, and see where your parcel is without calling anyone.',
    'courier_ordering_s1' => 'Open “New order” and make your order as usual.',
    'courier_ordering_s2' => 'In the “Courier” box, pick a courier. If any courier is fine, leave it on “Company decides”.',
    'courier_ordering_s3' => 'If you picked a courier, the parcel is booked with that courier by itself once your order is approved.',
    'courier_ordering_s4' => 'If you left it on “Company decides”, the office chooses the courier and sends the parcel.',
    'courier_ordering_s5' => 'Open the order. Under “Parcel tracking” you can see the step: Waiting for pickup, Picked up, On the way, Delivered. A parcel sent back shows “Returned”.',
    'courier_ordering_s6' => 'Press “Copy” to copy the tracking number. Press “Track on the courier website” to open the courier\'s own page.',
    'courier_ordering_s7' => 'If the office changes your courier, you get a notice. The order page shows the change and any note from the office.',
    'courier_ordering_o1' => 'You know which courier has your parcel and what the tracking number is.',
    'courier_ordering_o2' => 'You get a notice on the bell each time the parcel moves to a new step.',
    'courier_ordering_t1' => 'The system asks the courier for news every 30 minutes, and also when the order page is opened.',
    'courier_ordering_t2' => 'Give the tracking number to the person who will receive the parcel.',
    'courier_ordering_w1' => 'When the courier says “Delivered”, the order is still not finished. The office must confirm the delivery first. Commission comes only after that.',

    'courier_staff_badge' => 'Courier',
    'courier_staff_title' => 'Automatic booking and changing the courier',
    'courier_staff_summary' => 'When a dealer picks a courier, the parcel is booked by itself on approval. Staff can change the courier and leave a note.',
    'courier_staff_purpose' => 'An order with a chosen courier does not need a hand dispatch. A “Company decides” order is still dispatched by hand.',
    'courier_staff_why' => 'Automatic booking saves typing, and the dealer gets the tracking number sooner. The note tells the dealer why the courier changed.',
    'courier_staff_s1' => 'Owner: switch on the couriers in “SMS & courier setup”. Dealers can pick only those.',
    'courier_staff_s2' => 'Approve the order as usual. If the dealer picked a courier, stock comes out of the branch and the parcel is booked with that courier by itself.',
    'courier_staff_s3' => 'The goods come from the head office, unless another branch was chosen for the order.',
    'courier_staff_s4' => 'If the courier is switched off, no active branch holds stock, or the branch is short of stock, nothing is sent. You get a bell notice. Change the courier or dispatch by hand.',
    'courier_staff_s5' => 'For a “Company decides” order, open the order and use the dispatch form. Pick a courier under “Book with a courier (optional)”, or type the courier name and tracking number.',
    'courier_staff_s6' => 'To change the courier, open the order and go to “Change courier”. Pick the “New courier”, add a note for the dealer if you want, and press “Change courier”.',
    'courier_staff_s7' => 'If the courier has collected the parcel but the step has not moved, press “Mark picked up”.',
    'courier_staff_s8' => 'When the goods have really arrived, press “Confirm delivery”. The courier saying “Delivered” does not finish the order.',
    'courier_staff_o1' => 'The dealer gets a notice. If you wrote a note, the dealer sees it too.',
    'courier_staff_o2' => 'The order history keeps every courier change.',
    'courier_staff_t1' => 'You can change the courier only before the booking is made, or after the courier refused it.',
    'courier_staff_t2' => 'These buttons are for staff who handle orders or stock. Nobody can use them on their own order.',
    'courier_staff_w1' => 'Approval books the parcel straight away. Check the order carefully before you approve it.',

    'deliveries_board_badge' => 'Deliveries',
    'deliveries_board_title' => 'The deliveries board and failed bookings',
    'deliveries_board_summary' => 'The Deliveries page lists every courier parcel and every booking the courier refused.',
    'deliveries_board_purpose' => 'Staff and the owner use this page to see where each parcel is and to fix refused bookings.',
    'deliveries_board_why' => 'A refused booking means the parcel has not left. This list keeps those orders in front of you.',
    'deliveries_board_s1' => 'Open “Deliveries” in the menu.',
    'deliveries_board_s2' => '“Failed bookings” is at the top. The courier did not accept these parcels. The “Problem” column says why.',
    'deliveries_board_s3' => 'Press the order number to open the order. Then press “Try booking again”, or use “Change courier”.',
    'deliveries_board_s4' => '“Courier parcels” lists every parcel booked with a courier. Choose a “Step” or a “Courier” and press “Show”.',
    'deliveries_board_s5' => 'Press a tracking number to open the courier\'s own page.',
    'deliveries_board_s6' => 'The page shows the branch picked in the top bar.',
    'deliveries_board_o1' => 'You can see how many parcels are at each step.',
    'deliveries_board_o2' => 'A failed booking leaves the list once it is booked.',
    'deliveries_board_t1' => 'You also get a bell notice when a booking fails.',
    'deliveries_board_w1' => 'If the “Problem” column says the courier gave no clear answer, the parcel may already be booked. Check the courier\'s own panel first. If it is there, do not book it again.',

    'notification_panel_badge' => 'Notifications',
    'notification_panel_title' => 'The bell and the notification panel',
    'notification_panel_summary' => 'Press the bell in the top bar to read your newest notices from any page.',
    'notification_panel_purpose' => 'The bell shows your 15 newest notices. A number on it tells you how many are unread.',
    'notification_panel_why' => 'You see order, payment and company news quickly, without leaving the page you are on.',
    'notification_panel_s1' => 'Look at the bell in the top bar. A number on it means you have unread notices.',
    'notification_panel_s2' => 'Press the bell. On a computer a small panel opens. On a phone it covers the screen.',
    'notification_panel_s3' => 'Press a notice to open it. It then counts as read.',
    'notification_panel_s4' => 'Press “Mark all as read” to clear every unread notice at once.',
    'notification_panel_s5' => 'Press “See all notifications” at the bottom for the full list.',
    'notification_panel_s6' => 'To close it, press the X or anywhere outside the panel.',
    'notification_panel_o1' => 'The number on the bell goes down as you read.',
    'notification_panel_t1' => 'Order news, payment news and support replies all come here.',
    'notification_panel_w1' => 'Never give anyone your password or OTP, even if a message asks for it.',

    'branch_switcher_badge' => 'Branches',
    'branch_switcher_title' => 'Changing branch from the top bar',
    'branch_switcher_summary' => 'Pick a branch in the top bar and the office pages show only that branch.',
    'branch_switcher_purpose' => 'Office staff and the owner have a branch list in the top bar. Dealers and sub-dealers do not have it.',
    'branch_switcher_why' => 'You can look at one branch\'s work without mixing it with the others.',
    'branch_switcher_s1' => 'Press the branch name in the top bar. On a phone it is under the page title.',
    'branch_switcher_s2' => 'The owner, and staff who work with accounts, stock or finance, see every branch and also “All branches”.',
    'branch_switcher_s3' => 'Other staff see only the branches they are assigned to. They do not get “All branches”.',
    'branch_switcher_s4' => 'Staff with no branch do not get the list. Pages that follow the branch stay empty until the owner gives them one.',
    'branch_switcher_s5' => 'Pick a branch. Dashboard, Orders, Deliveries, Check order payments, Withdrawal requests, Reports, Top sellers, Dealers, Sub-dealers and Staff list then show that branch. The head office also shows new orders, dealers and sub-dealers that have no branch yet.',
    'branch_switcher_s6' => 'These pages say which branch you are looking at, for example “Showing: Head Office”.',
    'branch_switcher_o1' => 'You see the numbers for one branch at a time.',
    'branch_switcher_t1' => 'Check the branch name before you record stock or anything else for a branch.',
    'branch_switcher_w1' => 'Staff cannot open a branch they are not assigned to, even by typing its address.',

    'website_button_badge' => 'Website',
    'website_button_title' => 'The “Visit website” button',
    'website_button_summary' => 'The globe in the top bar opens the company\'s public website.',
    'website_button_purpose' => 'You can go from your panel to the public website with one press.',
    'website_button_why' => 'You can see product pages and company details the way customers see them.',
    'website_button_s1' => 'Press the globe in the top bar. Its name is “Visit website”.',
    'website_button_s2' => 'The public website opens in the same browser tab.',
    'website_button_s3' => 'To come back, press your browser\'s back button.',
    'website_button_s4' => 'The same link is in the menu under your photo.',
    'website_button_o1' => 'You see the website the way customers see it.',
    'website_button_t1' => 'To keep your panel open, open the website in a new browser tab.',
    'website_button_w1' => 'Going to the website does not log you out. On someone else\'s computer, log out when you finish.',

    'prescriptions_partner_badge' => 'Prescriptions',
    'prescriptions_partner_title' => 'Prescriptions for dealers and sub-dealers',
    'prescriptions_partner_summary' => 'Once your registration is checked, you can keep patients and write prescriptions.',
    'prescriptions_partner_purpose' => 'Prescriptions are off for every dealer and sub-dealer at first. The menu item appears only after your registration is checked and prescriptions are turned on.',
    'prescriptions_partner_why' => 'A prescription is a medical paper. Only someone with a checked registration should write one.',
    'prescriptions_partner_s1' => 'Show your registration papers (BMDC, Unani board or Ayurvedic board) to the owner or the office. They check them and turn prescriptions on.',
    'prescriptions_partner_s2' => 'After that, open “Prescriptions” from the menu.',
    'prescriptions_partner_s3' => 'On the “Patients” tab, fill in “New patient” and press “Save patient”.',
    'prescriptions_partner_s4' => 'On the “Prescriptions” tab, go to “New prescription” and choose the patient.',
    'prescriptions_partner_s5' => 'For each medicine, type the name, dose, how often and how long. Then type the price, quantity and any discount.',
    'prescriptions_partner_s6' => 'Press “Add medicine” for another line. Check the total and press “Save prescription”.',
    'prescriptions_partner_s7' => 'Press “Print (Bangla)” or “Print (English)” to print it.',
    'prescriptions_partner_o1' => 'Only you can see your patients and prescriptions. Not even the owner can see them.',
    'prescriptions_partner_o2' => 'The total is worked out from your price, quantity and discount.',
    'prescriptions_partner_t1' => 'One prescription can hold up to 30 medicines.',
    'prescriptions_partner_t2' => 'Your registration number is printed on the prescription.',
    'prescriptions_partner_w1' => 'These medicines are typed by you and do not come from company stock. They are not company orders and earn no commission.',

    'prescriptions_verify_badge' => 'Prescriptions',
    'prescriptions_verify_title' => 'Turning prescriptions on for a dealer or sub-dealer',
    'prescriptions_verify_summary' => 'The owner, or staff with the “Verify prescribers” permission, turn prescriptions on after checking the registration.',
    'prescriptions_verify_purpose' => 'Every dealer and sub-dealer starts with prescriptions off. It stays off until someone checks the papers and turns it on.',
    'prescriptions_verify_why' => 'Only people with a real registration should write prescriptions. Every change is written in the Work log.',
    'prescriptions_verify_s1' => 'Check the partner\'s registration papers in person.',
    'prescriptions_verify_s2' => 'Find the partner in “Dealers” or “Sub-dealers” and press “Edit / status”.',
    'prescriptions_verify_s3' => 'In the “Prescriptions” box, choose the registration type: BMDC (allopathic), Unani board or Ayurvedic board.',
    'prescriptions_verify_s4' => 'Type the registration number, add a note if you want, and press “Turn on prescriptions”.',
    'prescriptions_verify_s5' => 'The partner now sees “Prescriptions” in the menu.',
    'prescriptions_verify_s6' => 'To stop it, write a reason if you want and press “Turn off”.',
    'prescriptions_verify_o1' => 'The box shows who turned it on or off, and when.',
    'prescriptions_verify_t1' => 'Owner: to let a staff member do this, give them the “Verify prescribers” permission on the “Staff list” page.',
    'prescriptions_verify_w1' => 'Turn it on only after you have seen the papers yourself.',

    'clinic_prescriptions_badge' => 'Clinic',
    'clinic_prescriptions_title' => 'The owner\'s clinic prescriptions',
    'clinic_prescriptions_summary' => 'The owner writes prescriptions from company products and gives the medicines from a branch.',
    'clinic_prescriptions_purpose' => 'When the owner gives the medicines, stock leaves the chosen branch and the money is split into two funds.',
    'clinic_prescriptions_why' => 'The manufacturer\'s share and the clinic\'s share are written down for every prescription, so the totals stay clear.',
    'clinic_prescriptions_s1' => 'Open “Prescriptions” from the menu. The Super Admin login always has this page. An office account has it only after it is turned on for that account.',
    'clinic_prescriptions_s2' => 'The first time, open the “Settings” tab and save your registration type and number. They are printed on your prescriptions.',
    'clinic_prescriptions_s3' => 'On the “Patients” tab, add the patient.',
    'clinic_prescriptions_s4' => 'On the “Prescriptions” tab, go to “New prescription”. For each line choose a company product. The name and MRP come from the product. Set your price, quantity and any discount.',
    'clinic_prescriptions_s5' => 'Press “Save prescription”. The status shows “Written”.',
    'clinic_prescriptions_s6' => 'In the list, choose the branch and press “Dispense”, then confirm. Stock leaves that branch and the status shows “Dispensed”.',
    'clinic_prescriptions_s7' => 'Open the “Clinic report” tab to see sales, the manufacturer fund and the clinic fund for any dates.',
    'clinic_prescriptions_o1' => '30% of each product\'s MRP goes to the manufacturer fund.',
    'clinic_prescriptions_o2' => 'The rest of your price goes to the clinic fund.',
    'clinic_prescriptions_o3' => 'No dealer order or dealer commission is made.',
    'clinic_prescriptions_t1' => 'Example: MRP ৳100 and your price ৳70. ৳30 goes to the manufacturer fund and ৳40 to the clinic fund.',
    'clinic_prescriptions_t2' => 'Each prescriber sees only their own patients and prescriptions. You cannot see a partner\'s patients, and you can dispense only your own clinic prescriptions.',
    'clinic_prescriptions_w1' => 'A price below 30% of MRP is stopped unless you change it in “Settings”. If you allow it, the clinic fund goes below zero.',

    // First-login tour steps for these features (read by TourGuide).
    'tour_bell_title' => 'Notifications',
    'tour_bell_loc' => 'The bell in the top bar',
    'tour_bell_body' => 'The bell opens a panel with your 15 newest notices. A number on it means you have unread ones.',
    'tour_bell_action' => 'Press the bell. Press a notice to open it, or press “Mark all as read”.',
    'tour_bell_tip' => 'Press “See all notifications” at the bottom for the full list.',

    'tour_website_title' => 'Visit website',
    'tour_website_loc' => 'The globe in the top bar',
    'tour_website_body' => 'The globe opens the company\'s public website in the same tab.',
    'tour_website_action' => 'Press the globe. To come back, press your browser\'s back button.',
    'tour_website_tip' => 'The same link is in the menu under your photo.',

    'tour_branch_title' => 'Changing branch',
    'tour_branch_loc' => 'Top bar (on a phone, under the page title)',
    'tour_branch_body' => 'Pick a branch and office pages such as Orders and Deliveries show only that branch. The owner, and staff who work with accounts, stock or finance, also get “All branches”. Other staff see only their own branches.',
    'tour_branch_action' => 'Press the branch name and choose one.',
    'tour_branch_tip' => 'These pages say which branch you are looking at.',

    'tour_partner_courier_title' => 'Courier and parcel tracking',
    'tour_partner_courier_loc' => 'The order form and the order page',
    'tour_partner_courier_body' => 'When you order, pick a courier or leave it on “Company decides”. If you pick one, the parcel is booked after approval. The order page then shows the tracking number and where the parcel is.',
    'tour_partner_courier_action' => 'Press an order to see its parcel. Press “Copy” to copy the tracking number.',
    'tour_partner_courier_tip' => 'You get a bell notice each time the parcel moves to a new step.',

    'tour_office_courier_title' => 'Courier booking',
    'tour_office_courier_loc' => 'Menu → Deliveries',
    'tour_office_courier_body' => 'If the dealer picked a courier, the parcel is booked by itself when the order is approved. If the courier refuses it, the order shows under “Failed bookings” on the Deliveries page.',
    'tour_office_courier_action' => 'Open the order to try booking again, or change the courier and add a note for the dealer.',
    'tour_office_courier_tip' => 'The courier saying “Delivered” does not finish the order. Staff must still confirm the delivery.',

    'tour_partner_rx_title' => 'Prescriptions',
    'tour_partner_rx_loc' => 'Menu → Prescriptions',
    'tour_partner_rx_body' => 'Prescriptions are on for your account. Add a patient, then type each medicine with its price and discount. Nothing comes from company stock.',
    'tour_partner_rx_action' => 'Open “Prescriptions” and fill in “New prescription”.',
    'tour_partner_rx_tip' => 'You can print a prescription in Bangla or English.',

    'tour_owner_rx_title' => 'Clinic prescriptions',
    'tour_owner_rx_loc' => 'Menu → Prescriptions',
    'tour_owner_rx_body' => 'Write prescriptions from company products, then pick a branch and press “Dispense”. Stock leaves that branch. 30% of MRP goes to the manufacturer fund and the rest to the clinic fund.',
    'tour_owner_rx_action' => 'Open “Prescriptions” and fill in “New prescription”.',
    'tour_owner_rx_tip' => 'The “Clinic report” tab shows the totals for any dates.',

    // Chapters for the new menu and the features added in November 2026.

    'menu_office_badge' => 'Office menu',
    'menu_office_title' => 'Where things are in the office menu',
    'menu_office_summary' => 'The office menu is one plain list in four blocks: daily work first, rarely used settings last.',
    'menu_office_purpose' => 'A row in the menu can hold several pages. They show as tabs along the top of the page. This chapter tells you what is in each row. You see only the rows and tabs you have permission for.',
    'menu_office_why' => 'If you cannot find a page, it may have moved. Check here before asking for access.',
    'menu_office_s1' => 'Daily work: Dashboard, Orders, Check order payments and Deliveries are rows of their own.',
    'menu_office_s2' => 'Messages & support has Partner messages, Support requests and Website enquiries.',
    'menu_office_s3' => 'Treasury is one row. Inside it are Funds, Order report, All events, Partners\' money and Money tasks.',
    'menu_office_s4' => 'Withdrawal requests and Commission rules & rates are rows of their own. Commission rules & rates has four tabs.',
    'menu_office_s5' => 'Products & stock has Products, Stock, Batches & expiry, Purchases, Stock counts and Branches.',
    'menu_office_s6' => 'Dealers & sub-dealers has Dealers, Sub-dealers, Who is under whom, Area dealers and Ranks. Applications has Dealer applications and Sub-dealer applications.',
    'menu_office_s7' => 'For partners has Schemes, Contests, Sales kit, Training, Meetings and Agreement. Staff has Staff list, Staff salary, SR areas & targets, Field sales and Roles & permissions.',
    'menu_office_s8' => 'Reports has Top sellers, Partner scorecard, Branch sales and Files. Website has Arrange the website, Page text, Trust page, Videos and Customer reviews, and for the owners only, Visitors. Everything else is on the Settings page.',
    'menu_office_o1' => 'You can reach every page you are allowed to use from one list.',
    'menu_office_t1' => 'Type a page name in “Search menu” at the top of the menu to jump to it.',
    'menu_office_w1' => 'A page that is not in your menu is not broken. You do not have permission for it. Ask the owner.',

    'menu_partner_badge' => 'Your menu',
    'menu_partner_title' => 'Where things are in your menu',
    'menu_partner_summary' => 'Your menu now starts with the day\'s work. Some pages moved and some have new names.',
    'menu_partner_purpose' => 'This chapter shows dealers and sub-dealers where each page is now.',
    'menu_partner_why' => 'Knowing the new place of a page saves you a call to the office.',
    'menu_partner_s1' => 'Home is your dashboard. New order starts a new order.',
    'menu_partner_s2' => 'My orders has Orders and Deliveries. Products is a row of its own.',
    'menu_partner_s3' => 'My money is one page: what you have, where it came from and every movement.',
    'menu_partner_s4' => 'My team has Team, Customers, Ranks, Top sellers and Contests. Sub-dealers have Customers, Top sellers and Contests.',
    'menu_partner_s5' => 'Sub-dealers: salary lines are in My money. Choose Salary in the list filter.',
    'menu_partner_s6' => 'Training & meetings has Training, Meetings and Sales kit.',
    'menu_partner_s7' => 'Contact the office has Messages, Notices, Give feedback and Help.',
    'menu_partner_s8' => 'My account has Profile, Security and Agreement.',
    'menu_partner_o1' => 'You can find every page without guessing.',
    'menu_partner_t1' => 'Type a page name in “Search menu” to jump to it.',
    'menu_partner_w1' => 'If the office has switched a page off for your account type, it will not be in your menu.',

    'commission_tabs_badge' => 'Commission pages',
    'commission_tabs_title' => 'Commission rules & rates: one page with four tabs',
    'commission_tabs_summary' => 'The commission pages are now tabs on one page.',
    'commission_tabs_purpose' => 'Open Commission rules & rates in the menu. Staff with finance permission and the owner see this page.',
    'commission_tabs_why' => 'You no longer have to look through the menu for each commission setting.',
    'commission_tabs_s1' => 'Open Commission rules & rates in the menu.',
    'commission_tabs_s2' => 'Set the commission split: how commission is shared on each sale.',
    'commission_tabs_s3' => 'Written commission rules: the rules partners are paid by.',
    'commission_tabs_s4' => 'One person\'s special rate: a different commission rate for one partner.',
    'commission_tabs_s5' => 'Commission calculator: try out a sale to see who earns what.',
    'commission_tabs_o1' => 'You can move between the commission settings with one press.',
    'commission_tabs_t1' => 'Try a change in the calculator first. The calculator never moves money.',
    'commission_tabs_w1' => 'Change rates only with written approval and a start date.',

    'report_centre_badge' => 'Report files',
    'report_centre_title' => 'Report files',
    'report_centre_summary' => 'Report files are on Treasury → Order report, under Download.',
    'report_centre_purpose' => 'Pick a file and the dates, then download it. You see only the files your job allows.',
    'report_centre_why' => 'One menu means you do not have to remember which file sits on which screen.',
    'report_centre_s1' => 'Open Treasury → Order report. Field staff open Reports → Files.',
    'report_centre_s2' => 'Choose the dates on the list.',
    'report_centre_s3' => 'Press Download and pick the file.',
    'report_centre_o1' => 'You get the file for the dates you chose.',
    'report_centre_t1' => 'Top sellers and Branch sales are under Reports.',
    'report_centre_w1' => 'Company-wide files are offered only to staff who may view every branch.',

    'my_money_tabs_badge' => 'My money',
    'my_money_tabs_title' => '“My money”: all your money on one page',
    'my_money_tabs_summary' => 'What you have, where it came from and every taka in and out.',
    'my_money_tabs_purpose' => 'Press My money in the menu. There are no separate pages to look through.',
    'my_money_tabs_why' => 'One page and one list make your money easy to count.',
    'my_money_tabs_s1' => 'The top shows what you can use now, what is waiting and what you asked to withdraw.',
    'my_money_tabs_s2' => 'Press a card, such as Direct referral, to see only that income in the list.',
    'my_money_tabs_s3' => 'Use search, filters and the date view on the list.',
    'my_money_tabs_s4' => 'Use Withdraw to take money out or order with it, and Download for files.',
    'my_money_tabs_o1' => 'You can see, withdraw and check your money from one page.',
    'my_money_tabs_t1' => 'The same income cards are on your home page.',
    'my_money_tabs_w1' => 'If Withdraw is not showing, read the notice on the page. It says why.',

    'support_one_form_badge' => 'Help request',
    'support_one_form_title' => 'Asking the office for help: one form',
    'support_one_form_summary' => 'One form now covers orders, NID corrections, payments and any other help.',
    'support_one_form_purpose' => 'The separate forms are gone. Use the help request form, and read the office\'s answer in the same place.',
    'support_one_form_why' => 'Every question and answer stays together, so nothing gets lost.',
    'support_one_form_s1' => 'Open Contact the office → Help.',
    'support_one_form_s2' => 'Press “Send a help request”.',
    'support_one_form_s3' => 'Choose the topic, write a subject and the details. You can add a photo or a PDF.',
    'support_one_form_s4' => 'Your requests are listed below the form. Press “See details” to read the office reply.',
    'support_one_form_o1' => 'All your requests and the answers are in one list.',
    'support_one_form_t1' => 'For a quick question, use Messages. For anything that needs a record, use this form.',
    'support_one_form_w1' => 'Do not write your password or full NID number in a request.',

    'website_editor_badge' => 'Website editor',
    'website_editor_title' => 'Changing the website: five parts and a search box',
    'website_editor_summary' => 'Arrange the website has five parts, a search box and a Save bar that stays in view.',
    'website_editor_purpose' => 'All the words, pictures and videos on the website are changed from here.',
    'website_editor_why' => 'You find the box you need quickly and you can see if your change is saved.',
    'website_editor_s1' => 'Open Website → Arrange the website.',
    'website_editor_s2' => 'Pick a part: Home page, Other pages, Text and policies, Videos, or Footer and contact.',
    'website_editor_s3' => 'Looking for one box? Type its name in the search box at the top, for example phone number.',
    'website_editor_s4' => 'Make your change, then press Save on the bar at the bottom. The bar says “Changes not saved yet” or “Everything is saved”.',
    'website_editor_s5' => 'Everything about videos is in the Videos part. The home page video has its own Save button.',
    'website_editor_s6' => 'Which product comes first on the home page: in the Home page part, type a number or use the arrows in the “Order of products on the home page” list, then press “Save the order”. The same list is under Products & stock → Products → Home page list.',
    'website_editor_o1' => 'Your change goes on the website after you save.',
    'website_editor_t1' => 'Look at the page on a phone and a computer after you save.',
    'website_editor_w1' => 'The reset button clears all your text and goes back to the starting text. It cannot be undone.',

    'stock_batches_badge' => 'Batches & expiry',
    'stock_batches_title' => 'Batches and expiry dates',
    'stock_batches_summary' => 'Stock is kept by batch. The batch that expires first goes out first, and expired stock is not sent.',
    'stock_batches_purpose' => 'Write the batch number when goods come in, and the expiry date too if you want to. The system then picks the right batch by itself.',
    'stock_batches_why' => 'Old stock goes out before it expires, and you can see which batch went to whom.',
    'stock_batches_s1' => 'When you add stock with Product in, or receive goods on a purchase order, type the batch number. The expiry date is optional: you get expiry warnings only for goods you gave a date.',
    'stock_batches_s2' => 'Open Products & stock → Batches & expiry.',
    'stock_batches_s3' => 'On the Expiring soon tab, press 30, 60 or 90 days to see what expires in that time.',
    'stock_batches_s4' => 'To change when warnings come, choose under “Warn me this many days before expiry” and press Save.',
    'stock_batches_s5' => 'Expired stock has its own list. Dispatch, courier booking and clinic dispense all skip it.',
    'stock_batches_s6' => 'Take expired stock off the shelf with Stock → Product out, reason Expired stock.',
    'stock_batches_o1' => 'Stock staff get a portal notice when a batch comes close to expiry or has expired.',
    'stock_batches_t1' => 'Customers can check the batch number on their pack on the website page /batch-check.',
    'stock_batches_w1' => 'If only expired units are left at a branch, those units cannot be sent.',

    'stock_recall_transfers_badge' => 'Recall & transfers',
    'stock_recall_transfers_title' => 'Batch recall, branch transfers and the reorder list',
    'stock_recall_transfers_summary' => 'Find who received a batch, move stock between branches, and see what to buy again.',
    'stock_recall_transfers_purpose' => 'These are the other tabs on Products & stock → Batches & expiry.',
    'stock_recall_transfers_why' => 'If a batch has a problem you know at once who has it. Stock moves between branches are written down.',
    'stock_recall_transfers_s1' => 'Batch recall: type the batch number and press “Find who received it”. You see the orders and partners, the clinic sales and what is still in stock.',
    'stock_recall_transfers_s2' => 'Branch transfers: fill in “New transfer request” and press “Request transfer”.',
    'stock_recall_transfers_s3' => 'When the goods leave, press Send. Stock leaves the branch and shows “On the way”.',
    'stock_recall_transfers_s4' => 'When the goods arrive, press Receive. Stock is added to the other branch.',
    'stock_recall_transfers_s5' => 'Reorder list: products at or below their minimum stock, with a suggested quantity.',
    'stock_recall_transfers_o1' => 'Stock in every branch matches what really moved.',
    'stock_recall_transfers_t1' => 'A transfer can be cancelled only before it is sent.',
    'stock_recall_transfers_w1' => 'Recall only shows the list. The system does not contact anyone, so call the partners yourself.',

    'purchasing_goods_badge' => 'Purchases',
    'purchasing_goods_title' => 'Purchases: suppliers, purchase orders and goods received',
    'purchasing_goods_summary' => 'Keep your suppliers, send them orders, and add goods to stock as they arrive.',
    'purchasing_goods_purpose' => 'Open Products & stock → Purchases. It has two tabs: Purchase orders and Suppliers.',
    'purchasing_goods_why' => 'You can see what was ordered, what came and what is still due.',
    'purchasing_goods_s1' => 'On the Suppliers tab, press “Add supplier”.',
    'purchasing_goods_s2' => 'On the Purchase orders tab, make a “New purchase order”: supplier, receiving branch, products and quantities. Press “Save as draft”.',
    'purchasing_goods_s3' => 'When you have sent it to the supplier, press “Mark as sent to supplier”.',
    'purchasing_goods_s4' => 'When goods arrive, open the order and go to “Receive goods”. Fill in only what came today: quantity and cost per unit. Add the batch no. and expiry date if you have them; both can be left blank. Press “Add to stock”.',
    'purchasing_goods_s5' => 'If the rest comes later, receive it the same way. The order shows Ordered, Received and Still due.',
    'purchasing_goods_s6' => 'To stop an order, press “Cancel order” and write why.',
    'purchasing_goods_o1' => 'Goods received go into stock at the receiving branch, with their batch and expiry when those were written.',
    'purchasing_goods_t1' => 'The cost per unit is shown only to staff who may see cost prices.',
    'purchasing_goods_w1' => 'You cannot receive more than is still due on the order. Goods already received stay in stock if the order is cancelled.',

    'stock_counting_badge' => 'Stock counts',
    'stock_counting_title' => 'Stock counts: comparing the shelf with the system',
    'stock_counting_summary' => 'Count what is on the shelf, compare it with the system, and send it for approval.',
    'stock_counting_purpose' => 'Open Products & stock → Stock counts. Stock changes only when a count is approved, and only by the difference.',
    'stock_counting_why' => 'Regular counts catch missing or extra goods early.',
    'stock_counting_s1' => 'Choose the branch and press “Start a count”.',
    'stock_counting_s2' => 'Type what you counted. Leave a line empty if you did not count it. Its stock will not change.',
    'stock_counting_s3' => 'Press “Save counts”, then “Send for approval”.',
    'stock_counting_s4' => 'When it is approved with “Approve and update stock”, stock is corrected by the difference. If it is rejected, stock is not changed.',
    'stock_counting_s5' => 'Press “Cancel this count” if you started it by mistake.',
    'stock_counting_o1' => 'Goods sold or received between the count and the approval are left alone.',
    'stock_counting_t1' => 'A branch with no approved count in 30 days shows as overdue, and stock staff get a portal notice.',
    'stock_counting_w1' => 'A branch can have only one open count at a time. Finish or cancel it first.',

    'parcel_received_back_badge' => 'Returned parcel',
    'parcel_received_back_title' => 'When the courier returns a parcel: “Parcel received back”',
    'parcel_received_back_summary' => 'Press “Parcel received back” once the parcel is back at the branch. The items return to stock.',
    'parcel_received_back_purpose' => 'A parcel the courier reports as returned cannot be confirmed as delivered. This button closes it properly.',
    'parcel_received_back_why' => 'Without it the items stay out of stock and the order stays open.',
    'parcel_received_back_s1' => 'Wait until the parcel is really back at the branch.',
    'parcel_received_back_s2' => 'Open the order. The parcel shows that the courier returned it.',
    'parcel_received_back_s3' => 'Press “Parcel received back”. You can add a note for the office.',
    'parcel_received_back_s4' => 'The items go back into stock. The order closes once nothing else is left on it.',
    'parcel_received_back_s5' => 'The dealer gets a notice to contact the office about the order.',
    'parcel_received_back_o1' => 'Stock is correct again, and no commission is paid for a returned parcel.',
    'parcel_received_back_t1' => 'This button shows only for staff with stock permission.',
    'parcel_received_back_w1' => 'Any money the dealer paid for this order must be returned by hand, outside this system.',

    'mixed_delivery_decision_badge' => 'Partly delivered',
    'mixed_delivery_decision_title' => 'One parcel delivered, another returned',
    'mixed_delivery_decision_summary' => 'Commission on the delivered goods is now automatic. Goods that came back go into stock again.',
    'mixed_delivery_decision_purpose' => 'When some parcels of an order are delivered and others come back, nobody has to decide anything for commission to be added.',
    'mixed_delivery_decision_why' => 'Commission follows the goods really delivered, the same way every time.',
    'mixed_delivery_decision_s1' => 'The order shows as partly delivered, and commission is worked out on the delivered goods.',
    'mixed_delivery_decision_s2' => 'The order page shows the value of the delivered goods and the order total.',
    'mixed_delivery_decision_s3' => 'To give no commission on such an order, open the order, press Give no commission and write the reason.',
    'mixed_delivery_decision_s4' => 'Then all of the commission goes to the company fund, and any commission partners already got is taken back.',
    'mixed_delivery_decision_o1' => 'Partners see the delivered value and the reason on the order page.',
    'mixed_delivery_decision_t1' => 'Only staff with the order review permission can give no commission.',
    'mixed_delivery_decision_w1' => 'Giving no commission cannot be changed once it is saved.',

    'manual_couriers_badge' => 'Manual couriers',
    'manual_couriers_title' => 'Couriers with no automatic booking',
    'manual_couriers_summary' => 'Sundarban, SA Paribahan, Karatoa, Janani and Continental are sent and updated by hand.',
    'manual_couriers_purpose' => 'These couriers have no booking system to connect to. Staff send the parcel and update its step.',
    'manual_couriers_why' => 'The dealer can still follow the parcel, as long as staff keep it up to date.',
    'manual_couriers_s1' => 'Owner: switch these couriers on in Settings → SMS and courier connections. A dealer can then pick one when ordering.',
    'manual_couriers_s2' => 'After approval you get a notice saying to send by hand. Send the parcel.',
    'manual_couriers_s3' => 'Open the order. In the courier panel choose the “New step” and type the “Consignment number”, then press “Save update”.',
    'manual_couriers_s4' => 'Update the step each time you hear from the courier. A parcel can only move forward.',
    'manual_couriers_s5' => 'When the goods have really arrived, press “Confirm delivery” as usual.',
    'manual_couriers_o1' => 'The dealer sees the step and the consignment number on the order page.',
    'manual_couriers_t1' => 'Sundarban and Janani have their own public tracking page, which the dealer can open from the order.',
    'manual_couriers_w1' => 'The system cannot hear from these couriers. If nobody updates the step, the dealer keeps seeing the old one.',

    'global_search_badge' => 'Search',
    'global_search_title' => 'Searching from the top bar',
    'global_search_summary' => 'Find an order, a partner or a product from any office page.',
    'global_search_purpose' => 'The Search button is in the top bar. You can also press Ctrl+K on the keyboard.',
    'global_search_why' => 'You can open what you need without going through the menu.',
    'global_search_s1' => 'Press Search in the top bar, or press Ctrl+K.',
    'global_search_s2' => 'Type at least 2 letters or numbers: an order number, name, code, phone or SKU.',
    'global_search_s3' => 'The results come in three groups: Orders, Partners and Products. Press one to open it.',
    'global_search_o1' => 'You reach the right order or partner in a few seconds.',
    'global_search_t1' => 'If nothing comes up, check the spelling or try a shorter word.',
    'global_search_w1' => 'You see only what your permission and branch allow. Phone numbers are always shown masked.',

    'company_funds_heads_badge' => 'Spending heads',
    'company_funds_heads_title' => 'Spending from funds, heads and budgets',
    'company_funds_heads_summary' => 'Every spend has a head. A budget warns you when a head goes over.',
    'company_funds_heads_purpose' => 'Spending heads and budgets are on Treasury → Money tasks.',
    'company_funds_heads_why' => 'Named heads show where company money is going.',
    'company_funds_heads_s1' => 'To spend, open the fund on Treasury → Funds and press Spend.',
    'company_funds_heads_s2' => 'Then it waits for approval under Money tasks → Waiting.',
    'company_funds_heads_s3' => 'Add or change heads under Money tasks → Spending heads.',
    'company_funds_heads_s4' => 'Set a monthly budget under Money tasks → Budgets.',
    'company_funds_heads_o1' => 'You can see spending by head and by month.',
    'company_funds_heads_t1' => 'A budget only warns. It never stops a spend.',
    'company_funds_heads_w1' => 'Check what the fund has now before you spend.',

    'accounting_statements_badge' => 'Files for the accountant',
    'accounting_statements_title' => 'Files for the accountant',
    'accounting_statements_summary' => 'Profit and loss, balance sheet and trial balance are downloaded as files.',
    'accounting_statements_purpose' => 'These three files are under Download on Treasury → Order report.',
    'accounting_statements_why' => 'Your accountant gets the same figures the system holds.',
    'accounting_statements_s1' => 'Open Treasury → Order report and choose the dates you need.',
    'accounting_statements_s2' => 'Press Download and pick the file.',
    'accounting_statements_o1' => 'The files cover exactly the dates you picked.',
    'accounting_statements_t1' => 'Send the files to your accountant every month.',
    'accounting_statements_w1' => 'These files are not a full set of accounts yet: sales and purchases are not in the journal, so those lines are added from other records and some are estimates. Do not use them as audited statements. They have company figures, so keep them private.',

    'statement_matching_badge' => 'Statement check',
    'statement_matching_title' => 'Matching a bank, bKash or Nagad statement',
    'statement_matching_summary' => 'Upload a statement and the system suggests which pending payment claims match it.',
    'statement_matching_purpose' => 'The Bank statement check on Treasury → Money tasks saves the time of checking each line by eye. Staff still decide.',
    'statement_matching_why' => 'A reference used twice or an amount that differs is easy to miss on paper. The system points them out.',
    'statement_matching_s1' => 'Open Treasury → Money tasks and press Bank statement check.',
    'statement_matching_s2' => 'Choose where the statement is from, give it a name, choose the CSV or Excel file and press “Upload statement”.',
    'statement_matching_s3' => 'Say which column holds the reference and which holds the money received. Date and details are optional. Choose the row where payments start and press “Find matches”.',
    'statement_matching_s4' => 'Read the result on each line: Match suggested, Same reference with a different amount, No pending claim, or Skipped.',
    'statement_matching_s5' => 'Press “Confirm match” if it is right, or “Turn down”. A line marked “Possibly fake” needs a note saying what you checked.',
    'statement_matching_s6' => 'Then approve the payment on Check order payments as usual.',
    'statement_matching_o1' => 'You can see which claims match the statement and which do not.',
    'statement_matching_t1' => 'The same file cannot be uploaded twice.',
    'statement_matching_w1' => 'The system never approves a payment. Confirming a match only records that you checked that line.',

    'payout_file_badge' => 'Bank file',
    'payout_file_title' => 'The file for the bank',
    'payout_file_summary' => 'One file with every approved withdrawal that is still unpaid.',
    'payout_file_purpose' => 'The button is on the Withdrawal requests page.',
    'payout_file_why' => 'Paying from one file saves typing and mistakes.',
    'payout_file_s1' => 'Open Withdrawal requests.',
    'payout_file_s2' => 'Press Download bank file and use it with the bank or bKash.',
    'payout_file_s3' => 'After paying, record each payment with its reference and receipt.',
    'payout_file_o1' => 'The file lists only approved withdrawals that are still unpaid.',
    'payout_file_t1' => 'Download the file just before you pay, so it is up to date.',
    'payout_file_w1' => 'The file does not pay anyone by itself. Record each payment after you pay.',

    'repeat_order_badge' => 'Order again',
    'repeat_order_title' => 'Ordering the same goods again',
    'repeat_order_summary' => 'One tap puts a past order in your cart with today\'s prices and stock.',
    'repeat_order_purpose' => 'The “Order again” box is on the New order page.',
    'repeat_order_why' => 'You do not have to pick the same products one by one.',
    'repeat_order_s1' => 'Open New order and find “Order again”.',
    'repeat_order_s2' => 'Press “Put in cart” on your last order or an earlier one.',
    'repeat_order_s3' => 'The page tells you if a price changed, if a quantity was lowered, or if an item cannot be ordered today.',
    'repeat_order_s4' => 'Check the items and prices, then pay in full and send proof as usual.',
    'repeat_order_o1' => 'Your cart is ready in one press.',
    'repeat_order_t1' => 'Items no longer sold or out of stock are left out by themselves.',
    'repeat_order_w1' => 'This only fills the cart. Nothing is ordered until you finish the order and pay.',

